/*
 * A281792  Primes of the form x^2 + p^4 where x > 0 and p is prime.
 * https://oeis.org/A281792
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   primes of the form x^2 + p^4, x>0, p prime. a(n) is the n-th
 *            such prime (a(1)=17). The sequence is generated by maintaining a
 *            min‑heap over all primes p; each node stores the current value
 *            p^4 + x^2. Popping the smallest node yields the next candidate
 *            and the node is advanced. All found primes ar...
 * Range:     u8 none, u16 none, u32 n <= 54, u64 n <= 10000, u128 n <= 10000,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>

#include "../utils/is_prime_big.h"

struct Node {
    seq_t val;          /* current candidate value p^4 + x^2 */
    seq_t p4;           /* fixed value p^4 for this prime p */
    uint64_t x;         /* current x   (>=1) */
};

/* ---------- global state ---------- */
static uint32_t *prime_list = NULL;     /* array of primes up to LIMIT */
static size_t prime_cnt  = 0;           /* number of primes stored       */

static struct Node *heap = NULL;        /* heap of all nodes             */
static size_t heap_size = 0;            /* current size of the heap      */

static seq_t *cache       = NULL;       /* cached terms of the sequence  */
static size_t cache_len   = 0;
static size_t cache_cap   = 0;

/* ---------- heap operations ---------- */
static void heapify_down(size_t i)
{
    while (1) {
        size_t l = 2 * i + 1;
        size_t r = l + 1;
        size_t smallest = i;
        if (l < heap_size && heap[l].val < heap[smallest].val) smallest = l;
        if (r < heap_size && heap[r].val < heap[smallest].val) smallest = r;
        if (smallest == i) break;
        struct Node tmp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = tmp;
        i = smallest;
    }
}

static void heap_build(void)
{
    for (size_t i = heap_size / 2; i-- > 0; ) heapify_down(i);
}

/* ---------- prime sieve ---------- */
static void init_primes(void)
{
    /* A generous upper bound; far more than needed for n≈10000 */
    const size_t LIMIT = 200000;
    bool *mark = (bool*)calloc(LIMIT + 1, sizeof(bool));
    if (!mark) return;
    for (size_t i = 2; i <= LIMIT; ++i) {
        if (!mark[i]) {
            prime_list = (uint32_t*)realloc(prime_list,
                                            (prime_cnt + 1) * sizeof(uint32_t));
            prime_list[prime_cnt++] = (uint32_t)i;
            if (i * i <= LIMIT) {
                for (size_t j = i * i; j <= LIMIT; j += i) mark[j] = true;
            }
        }
    }
    free(mark);
}

/* ---------- heap initialization ---------- */
static void init_heap(void)
{
    heap_size = prime_cnt;
    heap = (struct Node*)malloc(heap_size * sizeof(struct Node));
    for (size_t i = 0; i < prime_cnt; ++i) {
        uint32_t p = prime_list[i];
        seq_t sp = (seq_t)p;
        seq_t p2 = sp * sp;
        seq_t p4 = p2 * p2;
        heap[i].p4 = p4;
        heap[i].x  = 1;
        heap[i].val = p4 + (seq_t)1;   /* 1^2 = 1 */
    }
    heap_build();
}

/* ---------- cache helpers ---------- */
static void cache_add(seq_t v)
{
    if (cache_len == cache_cap) {
        size_t new_cap = cache_cap ? cache_cap << 1 : 64;
        seq_t *tmp = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) return;               /* unlikely, but safe */
        cache = tmp;
        cache_cap = new_cap;
    }
    cache[cache_len++] = v;
}

/* ---------- main function ---------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* offset starts at 1 */

    static bool initialized = false;
    if (!initialized) {
        init_primes();
        init_heap();
        initialized = true;
    }

    while (cache_len < (size_t)n) {
        /* Take the smallest candidate from the heap */
        struct Node *node = &heap[0];
        seq_t cand = node->val;

        /* Advance this prime's x and update its value */
        node->x++;
        seq_t nx = (seq_t)node->x;
        seq_t nx2 = nx * nx;
        node->val = node->p4 + nx2;
        heapify_down(0);

        /* Store if it is prime and not a duplicate */
        if (is_prime_big(cand)) {
            if (cache_len == 0 || cache[cache_len - 1] != cand) {
                cache_add(cand);
            }
        }
    }

    return cache[(size_t)n - 1];
}
